        .plat-list {
          cursor: pointer;
          display: flex;
          grid-gap: 20px;
          max-width: 1400px;
          width: 100%;
          margin: 10px auto 0;
          overflow: auto;
          padding: 10px 20px 20px;
          justify-content: flex-start;
          flex-wrap: wrap;

          .plat-item {
            padding: 10px;
            cursor: pointer;
            border-radius: 10px;
            background: #003653;
            z-index: 2;
            box-shadow: rgb(0 0 0 / 24%) 0px 6px 12px 0px;
            // min-width: 100px;
            text-align: center;

            img {
              max-height: 16px;
              filter: grayscale(1);
              display: block;
              margin: 0 auto;
            }

            &.active,
            &:hover {
              background: #1c5370;
              box-shadow: inset 0 0 5px #ffffff;

              img {
                filter: grayscale(0);
              }
            }
          }
        }
